mapper.select:
SELECT EXISTS(
    SELECT 1
    FROM sys_organization
    WHERE organization_code = #{code}
)

SELECT EXISTS(
    SELECT 1
    FROM sys_organization
    WHERE parent_scope_key = #{parentScopeKey}
      AND organization_name = #{name}
)

SELECT EXISTS(
    SELECT 1
    FROM sys_organization
    WHERE parent_scope_key = #{parentScopeKey}
      AND organization_name = #{name}
      AND id != #{excludedId}
)

mapper.update:
UPDATE sys_organization
SET effective_status = #{effectiveStatus},
    version_no = version_no + 1,
    updated_at = CURRENT_TIMESTAMP
WHERE id = #{id}
  AND version_no = #{expectedVersion}

UPDATE sys_organization
SET sort_order = #{sortOrder},
    version_no = version_no + 1,
    updated_at = CURRENT_TIMESTAMP
WHERE id = #{id}
  AND version_no = #{expectedVersion}

mapper.select:
SELECT id, parent_id, parent_scope_key, organization_code, organization_name, organization_type, organization_path, sort_order, status, effective_status, version_no, created_at, updated_at, admin_division_code FROM sys_organization
parent_id IS NULL parent_id = #{parentId}
ORDER BY sort_order ASC, organization_code ASC FOR UPDATE

mapper.delete:
DELETE FROM sys_organization
WHERE id = #{id}
  AND version_no = #{expectedVersion}
  AND NOT EXISTS (
      SELECT 1 FROM sys_organization child WHERE child.parent_id = #{id}
  )

mapper.select:
SELECT id, parent_id, parent_scope_key, organization_code, organization_name, organization_type, organization_path, sort_order, status, effective_status, version_no, created_at, updated_at, admin_division_code FROM sys_organization WHERE id IN
#{id}
ORDER BY organization_path ASC, sort_order ASC, organization_code ASC
